class Solution:
    def equationsPossible(self, equations: list[str]) -> bool:
        same = [[False] * 26 for _ in range(26)]
        for i in range(26):
            same[i][i] = True
        for eq in equations:
            if eq[1:3] == "==":
                a, b = ord(eq[0]) - 97, ord(eq[3]) - 97
                same[a][b] = same[b][a] = True
        for k in range(26):
            for i in range(26):
                for j in range(26):
                    same[i][j] = same[i][j] or (same[i][k] and same[k][j])
        for eq in equations:
            if eq[1:3] == "!=":
                a, b = ord(eq[0]) - 97, ord(eq[3]) - 97
                if same[a][b]:
                    return False
        return True

