class Solution:
    def equationsPossible(self, equations: list[str]) -> bool:
        g = [[] for _ in range(26)]
        for eq in equations:
            if eq[1:3] == "==":
                a, b = ord(eq[0]) - 97, ord(eq[3]) - 97
                g[a].append(b); g[b].append(a)
        comp = [-1] * 26; cid = 0
        for i in range(26):
            if comp[i] == -1:
                stack = [i]; comp[i] = cid
                while stack:
                    u = stack.pop()
                    for v in g[u]:
                        if comp[v] == -1:
                            comp[v] = cid; stack.append(v)
                cid += 1
        for eq in equations:
            if eq[1:3] == "!=":
                a, b = ord(eq[0]) - 97, ord(eq[3]) - 97
                if comp[a] == comp[b]:
                    return False
        return True

