class Solution:
    def equationsPossible(self, equations: list[str]) -> bool:
        parent = list(range(26))
        rank = [0] * 26
        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]; x = parent[x]
            return x
        def union(a, b):
            ra, rb = find(a), find(b)
            if ra == rb:
                return
            if rank[ra] < rank[rb]:
                ra, rb = rb, ra
            parent[rb] = ra
            if rank[ra] == rank[rb]:
                rank[ra] += 1
        for eq in equations:
            if eq[1:3] == "==":
                union(ord(eq[0]) - 97, ord(eq[3]) - 97)
        for eq in equations:
            if eq[1:3] == "!=" and find(ord(eq[0]) - 97) == find(ord(eq[3]) - 97):
                return False
        return True

